const $ = s => document.querySelector(s);
const topics=['全部','AI 与科技','思维与学习','科学与数学','社会与世界','人文与艺术','生活与成长'];
function read(key,fallback){try{const x=JSON.parse(localStorage.getItem(key));return Array.isArray(x)?x:fallback}catch{return fallback}}
const saved=new Set(read('ub-saved',[]).filter(id=>catalog.some(c=>c.id===id)));let history=read('ub-history',[]).filter(id=>catalog.some(c=>c.id===id)),questions=read('ub-questions',[]),view='explore',topic='全部',batch=0,deadline=null;
function persist(){try{localStorage.setItem('ub-saved',JSON.stringify([...saved]));localStorage.setItem('ub-history',JSON.stringify(history));localStorage.setItem('ub-questions',JSON.stringify(questions))}catch{toast('浏览器未允许存储，本次操作仍然有效')}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
$('.topics').innerHTML=topics.map(t=>`<button class="topic${t===topic?' active':''}" aria-pressed="${t===topic}" data-topic="${t}">${t}</button>`).join('');
[...new Set(catalog.map(c=>c.source))].forEach(s=>{const o=document.createElement('option');o.value=s;o.textContent=s;$('#source').append(o)});
function render(){
 const query=$('#search').value.trim().toLocaleLowerCase();let pool=view==='saved'?catalog.filter(c=>saved.has(c.id)):view==='history'?history.map(id=>catalog.find(c=>c.id===id)).filter(Boolean):catalog;
 pool=pool.filter(c=>(topic==='全部'||c.topic===topic)&&($('#source').value==='all'||c.source===$('#source').value)&&(!query||`${c.title} ${c.desc} ${c.author} ${c.tags} ${c.topic}`.toLocaleLowerCase().includes(query)));
 const finite=view==='explore'&&!query&&topic==='全部'&&$('#source').value==='all';const list=finite?pool.slice(batch*6,batch*6+6):pool;
 $('#cards').innerHTML=list.map(c=>`<article class="card"><div class="art" style="--art-bg:${c.color};--art-ink:${c.ink}"><a class="art-symbol" href="${c.url}" target="_blank" rel="noopener noreferrer" data-open="${c.id}" aria-label="在新标签页打开：${c.title}">${c.symbol.replace(/</g,'&lt;')}</a><span class="art-caption">${c.topic} / CURATED</span><span class="format">${c.format}</span><button class="save" data-save="${c.id}" aria-label="${saved.has(c.id)?'取消收藏':'收藏'}：${c.title}" aria-pressed="${saved.has(c.id)}">${saved.has(c.id)?'▣':'▱'}</button></div><div class="card-meta"><span class="source-dot"></span>${c.source}<span>·</span>${c.author}</div><a href="${c.url}" target="_blank" rel="noopener noreferrer" data-open="${c.id}"><h3>${c.title}</h3></a><p>${c.desc}</p><div class="card-bottom"><span>${c.topic} · ${c.level}</span><a class="open" href="${c.url}" target="_blank" rel="noopener noreferrer" data-open="${c.id}">原站阅读 ↗</a></div></article>`).join('');
 $('#empty').hidden=list.length>0;$('#batchEnd').hidden=list.length===0||view!=='explore';$('#more').hidden=!finite;
 $('#resultSummary').textContent=finite?`精选目录 ${catalog.length} 项 · 每次只呈现 6 项 · 第 ${batch+1} 组`:`找到 ${pool.length} 项内容${query?' · 仅搜索本站精选目录':''}`;
 $('#savedCount').textContent=saved.size;$('.spotlight').hidden=view!=='explore';
 $('#sectionTitle').textContent=view==='saved'?'留给未来的好奇心':view==='history'?'你走过的探索路径':'留一点时间，给新的发现';
 if(view==='history'&&questions.length){const section=document.createElement('section');section.className='question-list';const title=document.createElement('h3');title.textContent='我留下的问题';section.append(title);questions.slice(-5).reverse().forEach(q=>{const p=document.createElement('p');p.textContent=q.text;section.append(p)});$('#cards').append(section);$('#empty').hidden=true}
 $('.topics').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.topic===topic);b.setAttribute('aria-pressed',String(b.dataset.topic===topic))});
}
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);persist();render();return}const open=e.target.closest('[data-open]');if(open){history=[open.dataset.open,...history.filter(id=>id!==open.dataset.open)].slice(0,50);persist()}const t=e.target.closest('[data-topic]');if(t){topic=t.dataset.topic;batch=0;render()}const nav=e.target.closest('[data-view]');if(nav){view=nav.dataset.view;topic='全部';batch=0;$('#search').value='';$('#source').value='all';document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n===nav));$('#crumb').textContent=nav.childNodes[1].textContent.trim();render()}});
$('#searchForm').addEventListener('submit',e=>{e.preventDefault();batch=0;render();$('.library').scrollIntoView({block:'start'})});$('#search').addEventListener('input',()=>{batch=0;render()});$('#source').addEventListener('change',()=>{batch=0;render()});$('#themeButton').onclick=()=>{topic='思维与学习';render();$('.library').scrollIntoView({block:'start'})};$('#reset').onclick=()=>{view='explore';topic='全部';batch=0;$('#search').value='';$('#source').value='all';document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));$('#crumb').textContent='发现兴趣';render()};$('#more').onclick=()=>{batch=(batch+1)%Math.ceil(catalog.length/6);render();$('.library').scrollIntoView({block:'start'});toast('换一组精选内容，没有无限滚动')};
function updateTimer(){const b=$('#focus');b.classList.toggle('running',deadline!==null);if(deadline){const seconds=Math.max(0,Math.ceil((deadline-Date.now())/1000));b.querySelector('span').textContent=`${Math.floor(seconds/60).toString().padStart(2,'0')}:${(seconds%60).toString().padStart(2,'0')} · 结束探索`;if(seconds===0){deadline=null;$('#reflection').showModal();updateTimer()}}else b.querySelector('span').textContent='开始 20 分钟探索'}
$('#focus').onclick=()=>{if(deadline){deadline=null;$('#reflection').showModal()}else{deadline=Date.now()+20*60*1000;toast('20 分钟探索开始。提醒仅在此页面保持打开时生效。')}updateTimer()};setInterval(updateTimer,1000);
$('#saveQuestion').onclick=e=>{const text=$('#question').value.trim();if(!text){e.preventDefault();$('#question').focus();toast('写下一个问题，或选择暂时跳过');return}questions.push({text,date:new Date().toISOString()});persist();$('#question').value='';toast('问题已保存在「最近探索」');if(view==='history')render()};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#reflection').open){e.preventDefault();$('#search').focus()}});render();
